<template>
  <div class="page-title"><div><p class="eyebrow">{{ state.mode.toUpperCase() }} · {{ state.channel.toUpperCase() }}</p><h1>{{ state.scenario.title }}</h1><p>{{ state.scenario.brief }}</p></div><button @click="$emit('close')">Back to learning</button></div>
  <p class="alert" v-if="state.mode==='assessment'">Assessment: hints and coaching are unavailable. A passing result requires trainer approval.</p>
  <div class="player-layout"><section class="card">
    <template v-if="step"><p>Screen {{ state.current_step+1 }} of {{ state.scenario.steps.length }}</p><h2>{{ step.title }}</h2><p v-if="step.instructions">{{ step.instructions }}</p><p v-if="state.mode==='walkthrough'">{{ step.hint }}</p>
      <div v-if="image" class="screenshot-editor player-screenshot"><img :src="image" alt="Current procedure screen"><button v-for="h in step.hotspots" :key="h.id" class="region" :class="{correct:state.mode==='walkthrough'&&h.correct}" :style="regionStyle(h)" :disabled="busy||state.status!=='active'" @click="choose(h)">{{ h.label }}{{ state.mode==='walkthrough'&&h.correct?' ✓':'' }}</button></div>
      <form v-if="selected?.type==='input'" @submit.prevent="sendAction(selected,input)"><label>{{ selected.label }}<input v-model="input" maxlength="500" autofocus></label><button :disabled="busy">Submit input</button></form>
    </template><p v-else>All procedure screens completed. Review your conversation, then submit.</p>
    <p role="status">{{ feedback }}</p><p v-if="coachText" class="coach-feedback">{{ coachText }}</p>
    <div class="toolbar"><button v-if="state.mode!=='assessment'&&state.status==='active'" @click="getCoach" :disabled="busy">Ask the coach</button><button v-if="state.status==='active'" @click="submit" :disabled="busy">Submit {{ state.mode }}</button><button @click="refresh" :disabled="busy">Refresh status</button><button v-if="state.grading_status==='failed'" @click="retryGrade" :disabled="busy">Retry grading</button></div>
    <p v-if="state.grading_status==='queued'||state.grading_status==='running'" role="status">Grading {{ state.grading_status }}. Your evidence is saved.</p><p v-if="state.grading_error" class="alert">{{ state.grading_error }}</p>
    <article v-if="state.result"><h2>{{ state.result.score }} / 100 · {{ state.result.passed?'Passed':'Practice and retry' }}</h2><p>{{ state.status==='approved'?'Trainer approved':state.status==='retry'?'Trainer requested a retry':'Trainer approval pending' }}</p><p v-if="state.review_note">{{ state.review_note }}</p><div v-for="c in state.result.criteria" :key="c.key"><h3>{{ c.key }} · {{ c.score }}</h3><p>{{ c.feedback }}</p><small>Evidence: {{ c.evidenceIds.join(', ') }}</small></div><h3>Strengths</h3><ul><li v-for="s in state.result.strengths" :key="s">{{ s }}</li></ul><h3>Next steps</h3><ul><li v-for="s in state.result.improvements" :key="s">{{ s }}</li></ul></article>
  </section><section class="card" v-if="state.channel!=='workflow'"><h2>Customer conversation</h2><div class="bubble customer">{{ state.opening }}</div><button v-if="state.channel==='voice'" :disabled="busy" @click="playReply()">Play opening</button>
    <article v-for="t in state.turns" :key="t.id"><div class="bubble agent">{{ t.agent_text }}</div><div class="bubble customer" v-if="t.customer_text">{{ t.customer_text }}</div><button v-if="t.state==='failed'&&state.member===identity.user" :disabled="busy" @click="retryTurn(t)">Retry saved response</button><span v-if="t.state==='pending'">Reply pending…</span><button v-if="state.channel==='voice'&&t.state==='completed'" :disabled="busy" @click="playReply(t.id)">Play reply</button></article>
    <form v-if="state.status==='active'&&state.member===identity.user&&state.channel==='chat'" @submit.prevent="sendText"><label>Your response<textarea v-model="text" maxlength="8000" required></textarea></label><button :disabled="busy||unfinished">Send response</button></form>
    <div v-if="state.status==='active'&&state.member===identity.user&&state.channel==='voice'"><button v-if="!recording" @click="record" :disabled="busy||unfinished">Record response · up to 60 seconds</button><button v-else @click="stop">Stop recording</button><p role="status">{{ recording?'Recording… microphone is active.':'' }}</p><audio v-if="recordingUrl" :src="recordingUrl" controls></audio><button v-if="recordingBlob" @click="sendAudio" :disabled="busy">Send recording</button></div>
  </section></div>
  <section class="card" v-if="identity.staff && state.member!==identity.user"><h2>Trainer evidence</h2><p>{{ state.review_context?.reference }}</p><p>Expected outcome: {{ state.review_context?.outcome }}</p><table><thead><tr><th>Action</th><th>Value</th><th>Correct</th><th>Critical failure</th></tr></thead><tbody><tr v-for="e in state.events" :key="e.id"><td>{{ e.hotspot_id }}</td><td>{{ e.value }}</td><td>{{ e.correct }}</td><td>{{ e.critical }}</td></tr></tbody></table><label>Trainer feedback<textarea v-model="note" maxlength="4000"></textarea></label><div class="toolbar" v-if="state.status==='submitted'&&state.mode==='assessment'"><button @click="review('approved')" :disabled="busy||!state.result?.passed">Approve completion</button><button @click="review('retry')" :disabled="busy||!note.trim()">Request retry</button></div></section>
</template>
<script setup>
import { computed,onMounted,onBeforeUnmount,ref } from 'vue'
import { api,rememberRequest,requestId,screenshotUrl } from '../lib/api'
const props=defineProps(['initial','identity']);const emit=defineEmits(['changed','error','close'])
const state=ref(props.initial),busy=ref(false),image=ref(''),selected=ref(null),input=ref(''),text=ref(''),feedback=ref(''),coachText=ref(''),note=ref(''),recording=ref(false),recordingBlob=ref(null),recordingUrl=ref('')
const step=computed(()=>state.value.scenario.steps[state.value.current_step]),unfinished=computed(()=>state.value.turns.some(t=>t.state!=='completed'))
const regionStyle=h=>({left:h.x*100+'%',top:h.y*100+'%',width:h.w*100+'%',height:h.h*100+'%'})
let recorder=null,stream=null,timer=null,poll=null,audio=null,audioUrl=null
async function refresh(){state.value=await api('get_attempt',{name:state.value.name});image.value=step.value?await screenshotUrl(step.value.assetId):''}
async function run(fn){busy.value=true;try{await fn()}catch(e){emit('error',e);try{await refresh()}catch{}}finally{busy.value=false}}
function choose(h){if(h.type==='input'){selected.value=h;input.value=''}else sendAction(h,'')}
async function sendAction(h,value){await run(async()=>{const payload={attempt:state.value.name,step_id:step.value.id,hotspot_id:h.id,value};const key='bpo-action:'+state.value.name;const result=await api('action',{...payload,request_id:rememberRequest(key,payload)});sessionStorage.removeItem(key);feedback.value=result.correct===undefined?'Action recorded.':result.correct?'Correct action.':result.hint||'Review the process and try again.';selected.value=null;await refresh()})}
async function sendText(){await run(async()=>{const payload={attempt:state.value.name,text:text.value};const key='bpo-turn:'+state.value.name;await api('conversation',{...payload,request_id:rememberRequest(key,payload)});sessionStorage.removeItem(key);text.value='';await refresh()})}
async function retryTurn(t){await run(async()=>{await api('conversation',{attempt:state.value.name,request_id:requestId(),retry_turn:t.id});await refresh()})}
async function submit(){await run(async()=>{await api('submit',{attempt:state.value.name,request_id:requestId()});await refresh();emit('changed')})}
async function retryGrade(){await run(async()=>{await api('retry_grading',{attempt:state.value.name});await refresh()})}
async function getCoach(){await run(async()=>{coachText.value=(await api('coaching',{attempt:state.value.name})).text})}
async function review(decision){await run(async()=>{await api('review',{attempt:state.value.name,decision,note:note.value});await refresh();emit('changed')})}
async function record(){try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Microphone recording requires HTTPS and browser microphone support.');stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{recording.value=false;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());recordingBlob.value=new Blob(chunks,{type:recorder.mimeType});if(recordingUrl.value)URL.revokeObjectURL(recordingUrl.value);recordingUrl.value=URL.createObjectURL(recordingBlob.value)};recorder.start();recording.value=true;timer=setTimeout(stop,59_500)}catch(e){stream?.getTracks().forEach(t=>t.stop());emit('error',new Error(e.name==='NotAllowedError'?'Microphone access was denied. Allow it in your browser settings, then retry.':e.message))}}
function stop(){if(recorder&&recorder.state!=='inactive')recorder.stop()}
async function sendAudio(){await run(async()=>{const form=new FormData();form.set('attempt',state.value.name);form.set('request_id',rememberRequest('bpo-audio:'+state.value.name,{size:recordingBlob.value.size}));form.set('file',recordingBlob.value,'response.webm');await api('conversation',form);recordingBlob.value=null;sessionStorage.removeItem('bpo-audio:'+state.value.name);URL.revokeObjectURL(recordingUrl.value);recordingUrl.value='';await refresh()})}
async function playReply(turn){await run(async()=>{const response=await fetch('/api/method/bpo_coach.api.speech',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':window.bpoCoachBoot.csrf_token},body:JSON.stringify({attempt:state.value.name,turn})});if(!response.ok)throw Error('Speech generation failed. Your transcript is saved; retry playback.');audio?.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(await response.blob());audio=new Audio(audioUrl);await audio.play()})}
onMounted(async()=>{try{await refresh()}catch(e){emit('error',e)}poll=setInterval(()=>{if(!busy.value&&['queued','running'].includes(state.value.grading_status))refresh().catch(e=>emit('error',e))},5000)})
onBeforeUnmount(()=>{clearInterval(poll);clearTimeout(timer);stop();stream?.getTracks().forEach(t=>t.stop());audio?.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);if(recordingUrl.value)URL.revokeObjectURL(recordingUrl.value)})
</script>
